package com.bank.rddint.core;

// Property 4: optional Partitioner. Maps a key to a partition index by hash.
public class HashPartitioner {
    private final int numPartitions;

    public HashPartitioner(int numPartitions) {
        this.numPartitions = numPartitions;
    }

    public int numPartitions() { return numPartitions; }

    public int partitionFor(Object key) {
        // Non-negative modulo, like Spark's HashPartitioner.
        return Math.floorMod(key.hashCode(), numPartitions);
    }
}
