package com.bank.rddint.core;

// Property 3: a dependency on a parent RDD — narrow or wide.
public class Dependency {
    public enum Kind { NARROW, WIDE }

    private final RddDescriptor<?> parent;
    private final Kind kind;

    public Dependency(RddDescriptor<?> parent, Kind kind) {
        this.parent = parent;
        this.kind = kind;
    }
    public RddDescriptor<?> getParent() { return parent; }
    public Kind getKind() { return kind; }
    public boolean causesShuffle() { return kind == Kind.WIDE; }
}
