package com.bank.rddint.core;

import java.util.ArrayList;
import java.util.List;
import java.util.function.Function;
import java.util.logging.Logger;

// Models the 5 internal properties of an RDD.
public class RddDescriptor<T> {
    private static final Logger log = Logger.getLogger(RddDescriptor.class.getName());

    // (1) list of partitions
    private final List<List<T>> partitions;
    // (2) computation function per partition (how to compute one partition)
    private final Function<Integer, List<T>> computeFunction;
    // (3) dependencies / lineage
    private final List<Dependency> dependencies;
    // (4) optional Partitioner
    private final HashPartitioner partitioner;
    // (5) preferred locations per partition (data locality hints)
    private final List<String> preferredLocations;

    public RddDescriptor(List<List<T>> partitions,
                         Function<Integer, List<T>> computeFunction,
                         List<Dependency> dependencies,
                         HashPartitioner partitioner,
                         List<String> preferredLocations) {
        this.partitions = partitions;
        this.computeFunction = computeFunction;
        this.dependencies = dependencies;
        this.partitioner = partitioner;
        this.preferredLocations = preferredLocations;
    }

    public int numPartitions() { return partitions.size(); }
    public List<Dependency> getDependencies() { return dependencies; }
    public HashPartitioner getPartitioner() { return partitioner; }
    public String preferredLocation(int p) { return preferredLocations.get(p); }

    // (2) compute a specific partition on demand.
    public List<T> compute(int partitionIndex) {
        return computeFunction.apply(partitionIndex);
    }

    // Derive a NARROW child (e.g., map): 1 parent partition → 1 child partition.
    public <R> RddDescriptor<R> narrowMap(Function<T, R> f) {
        log.info("deriving NARROW child (map) — no shuffle");
        List<List<R>> childParts = new ArrayList<>();
        for (int i = 0; i < numPartitions(); i++) {
            List<R> cp = new ArrayList<>();
            for (T t : compute(i)) cp.add(f.apply(t));
            childParts.add(cp);
        }
        List<Dependency> deps = List.of(new Dependency(this, Dependency.Kind.NARROW));
        return new RddDescriptor<>(childParts, childParts::get, deps,
                partitioner, preferredLocations);
    }

    // Derive a WIDE child (e.g., groupBy by key via partitioner): shuffle!
    public RddDescriptor<T> wideRepartitionByKey(Function<T, Object> keyFn,
                                                 HashPartitioner newPart,
                                                 List<String> newLocations) {
        log.info("deriving WIDE child (repartition by key) — SHUFFLE required");
        List<List<T>> childParts = new ArrayList<>();
        for (int i = 0; i < newPart.numPartitions(); i++) childParts.add(new ArrayList<>());
        for (int i = 0; i < numPartitions(); i++) {
            for (T t : compute(i)) {
                int target = newPart.partitionFor(keyFn.apply(t)); // move across partitions
                childParts.get(target).add(t);
            }
        }
        List<Dependency> deps = List.of(new Dependency(this, Dependency.Kind.WIDE));
        return new RddDescriptor<>(childParts, childParts::get, deps,
                newPart, newLocations);
    }
}
