package com.bank.rddint;

import com.bank.rddint.core.*;
import com.bank.rddint.model.Txn;
import java.math.BigDecimal;
import java.util.List;
import java.util.logging.*;

public class RddInternalsDemo {
    private static final Logger log = Logger.getLogger(RddInternalsDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new IntLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        // (1) partitions, (5) preferred locations
        List<List<Txn>> parts = List.of(
            List.of(new Txn("SAV2001", new BigDecimal("1000"))),
            List.of(new Txn("CUR3001", new BigDecimal("500")),
                    new Txn("SAV2001", new BigDecimal("3000")))
        );
        List<String> locations = List.of("worker-1 (NODE_LOCAL)", "worker-2 (NODE_LOCAL)");
        HashPartitioner hp = new HashPartitioner(2);

        // Base RDD descriptor with all 5 properties.
        RddDescriptor<Txn> base = new RddDescriptor<>(
            parts, parts::get, List.of(), hp, locations);

        log.info(() -> "Base: partitions=" + base.numPartitions()
                + ", partitioner=HashPartitioner(" + hp.numPartitions() + ")"
                + ", loc[0]=" + base.preferredLocation(0));

        // Narrow child: map to amounts (no shuffle).
        RddDescriptor<BigDecimal> amounts = base.narrowMap(Txn::getAmount);
        log.info(() -> "Narrow child dep causesShuffle? "
                + amounts.getDependencies().get(0).causesShuffle());

        // Wide child: repartition txns by accountId (shuffle).
        RddDescriptor<Txn> byAccount = base.wideRepartitionByKey(
            Txn::getAccountId, new HashPartitioner(2), locations);
        log.info(() -> "Wide child dep causesShuffle? "
                + byAccount.getDependencies().get(0).causesShuffle());
    }
}

